"use client";

import { GlassCard } from "@/components/glass-card";
import { WeatherIcon } from "@/features/weather/components/weather-icon";
import { WeatherSky } from "@/features/weather/components/weather-sky";
import {
  formatHour,
  formatTemperature,
  skyPhase,
  summarizeWeather,
} from "@/features/weather/weather-schema";
import { cn } from "@/lib/utils";
import type { WeatherData } from "@/features/weather/weather-schema";

export type WeatherCardState = "streaming" | "loading" | "ready" | "error";

export interface WeatherCardProps {
  readonly state: WeatherCardState;
  /**
  The location from the props, shown before the data arrives.
  */
  readonly location?: string;
  readonly data?: WeatherData;
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = "relative isolate w-full max-w-sm rounded-2xl p-4";

export function WeatherCard({
  state,
  location,
  data,
  error,
  className,
}: WeatherCardProps) {
  if (state === "ready" && data) {
    return <WeatherReady data={data} className={className} />;
  }
  if (state === "error") {
    return (
      <WeatherError location={location} message={error} className={className} />
    );
  }
  return (
    <WeatherCardSkeleton
      location={location}
      streaming={state === "streaming"}
      className={className}
    />
  );
}

function WeatherReady({
  data,
  className,
}: {
  readonly data: WeatherData;
  readonly className?: string;
}) {
  const phase = skyPhase(data.asOf, data.sunrise, data.sunset);
  const sunProgress =
    (data.asOf - data.sunrise) / Math.max(data.sunset - data.sunrise, 1);
  return (
    <GlassCard
      surface="scene"
      label={summarizeWeather(data)}
      className={className}
      backdrop={
        <WeatherSky
          phase={phase}
          condition={data.condition}
          sunProgress={sunProgress}
        />
      }
    >
      <div className="flex flex-col gap-3">
        <header className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h3 className="truncate text-[15px] leading-5 font-semibold">
              {data.location}
            </h3>
            <p className="mt-1 text-5xl leading-none font-light tracking-tight tabular-nums">
              {formatTemperature(data.temperature)}
            </p>
          </div>
          <div className="flex shrink-0 flex-col items-end text-right text-[13px] leading-5 font-semibold">
            <WeatherIcon
              condition={data.condition}
              isDay={data.isDay}
              size={20}
              className="drop-shadow-sm"
            />
            <p className="mt-1.5">{data.label}</p>
            <p className="tabular-nums">
              H:{formatTemperature(data.high)} L:{formatTemperature(data.low)}
            </p>
          </div>
        </header>

        <ol className="grid grid-cols-6 text-center">
          {data.hours.map((hour) => (
            <li key={hour.time} className="flex flex-col items-center gap-1.5">
              <span className="text-[11px] leading-4 font-medium text-white/80">
                {formatHour(hour.time, data.timeZone)}
              </span>
              <WeatherIcon
                condition={hour.condition}
                isDay={hour.isDay}
                size={22}
                className="drop-shadow-sm"
              />
              <span className="text-[13px] leading-5 font-semibold tabular-nums">
                {formatTemperature(hour.temperature)}
              </span>
            </li>
          ))}
        </ol>
      </div>
    </GlassCard>
  );
}

function WeatherError({
  location,
  message,
  className,
}: {
  readonly location?: string;
  readonly message?: string;
  readonly className?: string;
}) {
  return (
    <div
      role="alert"
      className={cn(
        CARD_FRAME,
        "bg-card text-card-foreground flex flex-col gap-1 border",
        className
      )}
    >
      <p className="text-sm font-semibold">
        {location
          ? `Couldn't load the weather for ${location}`
          : "Couldn't load the weather"}
      </p>
      <p className="text-muted-foreground text-xs">
        {message ??
          "The weather service didn't respond. Try again in a moment."}
      </p>
    </div>
  );
}

/** The card while its data is on the way: the same frame and rows as the
 *  ready card, so nothing moves when the forecast lands. Shows the place as
 *  soon as it's known (with "…" while the model is still writing it). */
export function WeatherCardSkeleton({
  location,
  streaming = false,
  className,
}: {
  readonly location?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  return (
    <div
      role="status"
      className={cn(CARD_FRAME, "bg-muted text-foreground", className)}
    >
      <span className="sr-only">
        {location ? `Loading the weather for ${location}` : "Loading weather"}
      </span>
      <div aria-hidden className="flex flex-col gap-3">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            {location ? (
              <p className="truncate text-[15px] leading-5 font-semibold">
                {location}
                {streaming ? (
                  <span className="text-muted-foreground">…</span>
                ) : null}
              </p>
            ) : (
              <div className="flex h-5 items-center">
                <div className="bg-foreground/10 h-3.5 w-24 animate-pulse rounded" />
              </div>
            )}
            <div className="bg-foreground/10 mt-1 h-12 w-20 animate-pulse rounded-lg" />
          </div>
          <div className="flex flex-col items-end gap-1.5">
            <div className="bg-foreground/10 size-5 animate-pulse rounded-full" />
            <div className="bg-foreground/10 h-4 w-24 animate-pulse rounded" />
            <div className="bg-foreground/10 h-4 w-20 animate-pulse rounded" />
          </div>
        </div>
        <div className="grid grid-cols-6">
          {["a", "b", "c", "d", "e", "f"].map((key) => (
            <div key={key} className="flex flex-col items-center gap-1.5">
              <div className="bg-foreground/10 h-4 w-8 animate-pulse rounded" />
              <div className="bg-foreground/10 size-[22px] animate-pulse rounded-full" />
              <div className="bg-foreground/10 h-5 w-7 animate-pulse rounded" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import type { ReactNode } from "react";

/**
The frame every glass card shares: a 1rem radius held in a variable so the clip and the rim follow it. A card's plain states (loading, error) match it with rounded-2xl, the same 1rem.
*/
const GLASS_FRAME =
  "relative isolate w-full max-w-sm rounded-(--glass-radius) p-4 [--glass-radius:1rem]";

const GLASS_CLIP =
  "pointer-events-none absolute inset-0 rounded-[inherit] [clip-path:inset(0_round_var(--glass-radius))]";

/**
The glass slab: shading and, when the card has no border of its own, a rim of light, over the backdrop and under the text. Its highlights scale with --glass-light (1 by default), so a dark surface can take a softer glass than a bright sky.
*/
export function GlassSurface({ rim = true }: { readonly rim?: boolean }) {
  return (
    <div
      aria-hidden
      className="pointer-events-none absolute inset-0 rounded-[inherit]"
    >
      <div
        className="absolute inset-0 rounded-[inherit]"
        style={{
          boxShadow: [
            "inset 0 12px 24px -16px rgb(255 255 255 / calc(0.35 * var(--glass-light, 1)))",
            "inset 0 -18px 30px -18px rgb(0 0 0 / 0.35)",
            "inset 14px 0 28px -24px rgb(255 255 255 / calc(0.25 * var(--glass-light, 1)))",
          ].join(", "),
        }}
      />
      {rim ? (
        <div
          className="absolute inset-0 rounded-[inherit] p-px"
          style={{
            WebkitMask:
              "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
            WebkitMaskComposite: "xor",
            background:
              "linear-gradient(150deg, rgb(255 255 255 / calc(0.7 * var(--glass-light, 1))), rgb(255 255 255 / calc(0.12 * var(--glass-light, 1))) 35%, rgb(255 255 255 / calc(0.05 * var(--glass-light, 1))) 60%, rgb(255 255 255 / calc(0.4 * var(--glass-light, 1))))",
            mask: "linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0)",
          }}
        />
      ) : null}
    </div>
  );
}

const SURFACE = {
  card: "bg-card text-card-foreground border dark:[--glass-light:0.25]",
  scene:
    "text-white [--glass-light:0.25] [text-shadow:0_1px_2px_rgb(0_0_0/0.2)] dark:[--glass-light:1]",
} as const;

/**
A card under a slab of glass: light along the top, shade along the bottom, and one edge.

- "scene" (the weather card): the glass sits over a picture, the sky, and the text is white. Its edge is the glass rim. On a light page its highlights drop to a quarter, since a white rim against a white page reads as a puffy halo rather than glass.
- "card": the glass sits over the card's own themed surface, so it keeps its colors in light and dark. Its edge is the themed border, so it skips the rim rather than drawing a second line inside it. In dark mode its highlights drop to a quarter.
*/
export function GlassCard({
  surface = "card",
  backdrop,
  label,
  className,
  children,
}: {
  readonly surface?: keyof typeof SURFACE;
  /**
  Anything drawn under the glass: the sky, or a faint map.
  */
  readonly backdrop?: ReactNode;
  /**
  What a screen reader hears for the whole card.
  */
  readonly label: string;
  readonly className?: string;
  readonly children: ReactNode;
}) {
  return (
    <section
      aria-label={label}
      className={cn(GLASS_FRAME, SURFACE[surface], className)}
    >
      <div className={GLASS_CLIP}>
        {backdrop}
        <GlassSurface rim={surface === "scene"} />
      </div>
      <div className="relative">{children}</div>
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { WeatherCard } from "@/features/weather/components/weather-card";
import { loadWeather } from "@/features/weather/weather-requests";
import type {
  WeatherData,
  WeatherUnits,
} from "@/features/weather/weather-schema";

type Load =
  | { status: "loading" }
  | { status: "ready"; data: WeatherData }
  | { status: "error"; message: string };

export function LiveWeatherCard({
  location,
  units,
  streaming = false,
  className,
}: {
  readonly location?: string;
  /**
  Null or left out: the place's usual units.
  */
  readonly units?: WeatherUnits | null;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });

  useEffect(() => {
    if (streaming || !location) {
      return;
    }
    let isCancelled = false;
    setLoad({ status: "loading" });
    const run = async () => {
      try {
        const data = await loadWeather(location, units ?? undefined);
        if (!isCancelled) {
          setLoad({ data, status: "ready" });
        }
      } catch (error) {
        if (!isCancelled) {
          setLoad({
            message: Error.isError(error) ? error.message : "Weather failed.",
            status: "error",
          });
        }
      }
    };
    run();
    return () => {
      isCancelled = true;
    };
  }, [location, units, streaming]);

  if (streaming || !location) {
    return (
      <WeatherCard
        state="streaming"
        location={location}
        className={className}
      />
    );
  }
  if (load.status === "ready") {
    return <WeatherCard state="ready" data={load.data} className={className} />;
  }
  if (load.status === "error") {
    return (
      <WeatherCard
        state="error"
        location={location}
        error={load.message}
        className={className}
      />
    );
  }
  return (
    <WeatherCard state="loading" location={location} className={className} />
  );
}

import { useId } from "react";
import { atmosphere, seeded } from "@/features/weather/weather-atmosphere";
import { cn } from "@/lib/utils";
import type { CSSProperties } from "react";
import type {
  AtmosphereSpec,
  CirrusSpec,
  CloudFieldSpec,
  CloudSpec,
  DeckSpec,
  GlowSpec,
  HazeSpec,
  MoonSpec,
  PlanetSpec,
  RaysSpec,
  Rgb,
  StarsSpec,
  SunSpec,
} from "@/features/weather/weather-atmosphere";
import type {
  SkyPhase,
  WeatherCondition,
} from "@/features/weather/weather-schema";

const KEYFRAMES = `
@keyframes gw-drift { from { transform: translateX(-14px); } to { transform: translateX(14px); } }
@keyframes gw-fog { from { transform: translateX(-40px); } to { transform: translateX(40px); } }
@keyframes gw-fall { from { transform: translate3d(0, -40px, 0) rotate(14deg); } to { transform: translate3d(-64px, 260px, 0) rotate(14deg); } }
@keyframes gw-snow {
  0% { transform: translate3d(0, -12px, 0); }
  25% { transform: translate3d(7px, 54px, 0); }
  50% { transform: translate3d(-5px, 120px, 0); }
  75% { transform: translate3d(6px, 186px, 0); }
  100% { transform: translate3d(0, 252px, 0); }
}
@keyframes gw-twinkle { 0%, 100% { opacity: var(--gw-o); } 50% { opacity: calc(var(--gw-o) * 0.2); } }
@keyframes gw-glow { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.07); } }
@keyframes gw-rays { 0%, 100% { opacity: 1; transform: rotate(0deg); } 50% { opacity: 0.6; transform: rotate(2deg); } }
@keyframes gw-flash {
  0%, 84%, 100% { opacity: 0; }
  85% { opacity: 0.75; }
  86.5% { opacity: 0.1; }
  88% { opacity: 0.55; }
  91% { opacity: 0; }
}
@keyframes gw-sheet {
  0%, 60%, 100% { opacity: 0; }
  61% { opacity: 0.7; }
  62.5% { opacity: 0.2; }
  64% { opacity: 0.5; }
  67% { opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .gw-anim { animation-play-state: paused !important; }
}
`;

export function WeatherSky({
  phase,
  condition,
  sunProgress,
  className,
}: {
  readonly phase: SkyPhase;
  readonly condition: WeatherCondition;
  /**
  How far through the day the sun is, sunrise 0 to sunset 1: moves the day sun from east to west.
  */
  readonly sunProgress?: number;
  readonly className?: string;
}) {
  const sky = atmosphere(phase, condition, sunProgress);
  const [top, middle, bottom] = sky.sky;

  return (
    <div
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-0 overflow-hidden",
        className
      )}
    >
      <style href="genuicn-weather-sky" precedence="default">
        {KEYFRAMES}
      </style>
      <div
        className="absolute inset-0"
        style={{
          background: `linear-gradient(180deg, ${top} 0%, ${middle} 58%, ${bottom} 100%)`,
        }}
      />
      {sky.stars?.milkyWay ? <MilkyWay /> : null}
      {sky.stars ? <Stars stars={sky.stars} /> : null}
      {sky.planet ? <Planet planet={sky.planet} /> : null}
      {sky.horizonGlow ? <HorizonGlow glow={sky.horizonGlow} /> : null}
      <Haze haze={sky.haze} />
      {sky.sun ? <Sun sun={sky.sun} /> : null}
      {sky.moon ? <MoonLight moon={sky.moon} /> : null}
      {sky.rays ? <Rays rays={sky.rays} /> : null}
      {sky.cirrus ? <Cirrus cirrus={sky.cirrus} /> : null}
      {sky.clouds ? <CloudField field={sky.clouds} /> : null}
      {sky.deck ? <Deck deck={sky.deck} /> : null}
      {sky.underglow ? <Underglow glow={sky.underglow} /> : null}
      {sky.rainbow === null ? null : <Rainbow x={sky.rainbow} />}
      {sky.rainShafts ? <RainShafts shafts={sky.rainShafts} /> : null}
      {sky.fog ? <Fog fog={sky.fog} /> : null}
      {sky.tint ? (
        <div className="absolute inset-0" style={{ background: sky.tint }} />
      ) : null}
      <Precipitation condition={condition} sky={sky} />
      <div
        className="absolute inset-0"
        style={{
          background:
            "linear-gradient(180deg, rgb(0 0 0 / 0.1) 0%, rgb(0 0 0 / 0) 38%, rgb(0 0 0 / 0) 62%, rgb(0 0 0 / 0.14) 100%)",
        }}
      />
    </div>
  );
}

function MilkyWay() {
  const id = useId();
  return (
    <svg
      viewBox="0 0 400 220"
      preserveAspectRatio="xMidYMid slice"
      className="absolute inset-0 size-full"
    >
      <defs>
        <filter id={`${id}-glow`} x="0" y="0" width="100%" height="100%">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.018 0.03"
            numOctaves={4}
            seed={3}
          />
          <feColorMatrix
            type="matrix"
            values="0 0 0 0 0.86  0 0 0 0 0.88  0 0 0 0 1  1.8 0 0 0 -0.6"
          />
          <feGaussianBlur stdDeviation={1.5} />
        </filter>
        <linearGradient
          id={`${id}-band`}
          x1="0"
          x2="0"
          y1="0"
          y2="1"
          gradientTransform="rotate(-24 0.5 0.5)"
        >
          <stop offset="0.2" stopColor="#fff" stopOpacity={0} />
          <stop offset="0.38" stopColor="#fff" stopOpacity={0.8} />
          <stop offset="0.46" stopColor="#fff" stopOpacity={0.3} />
          <stop offset="0.52" stopColor="#fff" stopOpacity={0.85} />
          <stop offset="0.68" stopColor="#fff" stopOpacity={0} />
        </linearGradient>
        <mask id={`${id}-mask`}>
          <rect width="400" height="220" fill={`url(#${id}-band)`} />
        </mask>
      </defs>
      <g mask={`url(#${id}-mask)`} opacity={0.32}>
        <rect width="400" height="220" filter={`url(#${id}-glow)`} />
      </g>
    </svg>
  );
}

const STAR_COUNT = 56;
const STARS = (() => {
  const random = seeded(7);
  return Array.from({ length: STAR_COUNT }, (_, index) => ({
    delay: random() * 6,
    id: index,
    left: random() * 100,
    opacity: 0.35 + random() * 0.6,
    seconds: 3 + random() * 4,
    size: random() < 0.15 ? 2 : 1,
    top: random() * 64,
  }));
})();

function Stars({ stars }: { readonly stars: StarsSpec }) {
  const shown = STARS.filter((star) => star.top < stars.maxTop).slice(
    0,
    stars.count
  );
  return (
    <div className="absolute inset-0" style={{ opacity: stars.opacity }}>
      {shown.map((star) => (
        <span
          key={star.id}
          className="gw-anim absolute rounded-full bg-white"
          style={
            {
              "--gw-o": star.opacity,
              animation: `gw-twinkle ${star.seconds}s ease-in-out ${-star.delay}s infinite`,
              height: star.size,
              left: `${star.left}%`,
              opacity: star.opacity,
              top: `${star.top}%`,
              width: star.size,
            } as CSSProperties
          }
        />
      ))}
    </div>
  );
}

function Planet({ planet }: { readonly planet: PlanetSpec }) {
  return (
    <span
      className="absolute size-[3px] -translate-1/2 rounded-full bg-[#fffbea]"
      style={{
        boxShadow:
          "0 0 4px 1px rgb(255 250 225 / 0.8), 0 0 12px 3px rgb(255 240 210 / 0.25)",
        left: `${planet.x}%`,
        top: `${planet.y}%`,
      }}
    />
  );
}

function HorizonGlow({ glow }: { readonly glow: GlowSpec }) {
  return (
    <div
      className="absolute inset-x-0 bottom-0 h-3/4"
      style={{
        background: `radial-gradient(90% 95% at ${glow.x}% 108%, ${glow.color} 0%, transparent 72%), radial-gradient(160% 60% at 50% 110%, ${glow.color} 0%, transparent 60%)`,
        opacity: glow.opacity,
      }}
    />
  );
}

function Underglow({ glow }: { readonly glow: GlowSpec }) {
  return (
    <div
      className="absolute inset-x-0 bottom-0 h-1/2"
      style={{
        background: `radial-gradient(70% 70% at ${glow.x}% 100%, ${glow.color} 0%, transparent 75%), linear-gradient(0deg, ${glow.color} 0%, transparent 45%)`,
        opacity: glow.opacity,
      }}
    />
  );
}

function Haze({ haze }: { readonly haze: HazeSpec }) {
  if (haze.opacity <= 0) {
    return null;
  }
  return (
    <div
      className="absolute inset-x-0 bottom-0"
      style={{
        background: `linear-gradient(0deg, rgb(${haze.color} / ${haze.opacity}) 0%, rgb(${haze.color} / ${haze.opacity * 0.45}) 45%, transparent 100%)`,
        height: `${haze.height * 100}%`,
      }}
    />
  );
}

function Sun({ sun }: { readonly sun: SunSpec }) {
  const isPale = sun.look === "pale";
  return (
    <div
      className="absolute -translate-x-1/2 -translate-y-1/2"
      style={{
        height: sun.size,
        left: `${sun.x}%`,
        opacity: sun.opacity,
        top: `${sun.y}%`,
        width: sun.size,
      }}
    >
      <div
        className="gw-anim absolute inset-0 rounded-full"
        style={{
          animation: isPale ? undefined : "gw-glow 9s ease-in-out infinite",
          background: `radial-gradient(circle, ${sun.color} 0%, transparent 62%)`,
          opacity: isPale ? 0.3 : 1,
        }}
      />
      <SunDisc sun={sun} />
    </div>
  );
}

function SunDisc({ sun }: { readonly sun: SunSpec }) {
  if (sun.look === "pale") {
    return (
      <div
        className="absolute top-1/2 left-1/2 size-[30px] -translate-1/2 rounded-full blur-[0.6px]"
        style={{
          background:
            "radial-gradient(circle, rgb(255 253 244 / 0.95) 0 64%, rgb(255 250 236 / 0.6) 100%)",
        }}
      />
    );
  }
  if (sun.look !== "disc") {
    return null;
  }
  if (sun.horizon) {
    return <HorizonSun color={sun.color} />;
  }
  return (
    <div
      className={cn(
        "absolute top-1/2 left-1/2 -translate-1/2 rounded-full",
        sun.small ? "size-5" : "size-[26px]"
      )}
      style={{
        background: "radial-gradient(circle, #fffdf2 0 55%, #fff1c4 100%)",
        boxShadow: `0 0 24px 8px ${sun.color}`,
      }}
    />
  );
}

function HorizonSun({ color }: { readonly color: string }) {
  return (
    <>
      <div
        className="absolute top-1/2 left-1/2 size-16 -translate-1/2 rounded-full"
        style={{
          background:
            "radial-gradient(circle, rgb(255 226 150 / 0.85) 0%, rgb(255 170 90 / 0.35) 40%, transparent 70%)",
        }}
      />
      <div
        className="absolute top-1/2 left-1/2 h-[21px] w-6 -translate-1/2 rounded-full"
        style={{
          background:
            "radial-gradient(circle at 50% 42%, #ffe2a0 0 22%, #ffb84d 58%, #ff7f35 100%)",
          maskImage:
            "linear-gradient(180deg, #000 0%, #000 42%, rgb(0 0 0 / 0.35) 62%, transparent 82%)",
        }}
      />
      <div
        className="absolute top-[calc(50%+4px)] left-1/2 h-2.5 w-[150px] -translate-x-1/2 rounded-full blur-[3px]"
        style={{
          background: `radial-gradient(50% 50% at 50% 50%, ${color} 0%, transparent 100%)`,
          opacity: 0.55,
        }}
      />
    </>
  );
}

function MoonLight({ moon }: { readonly moon: MoonSpec }) {
  const isHalo = moon.look === "halo";
  return (
    <div
      className="absolute size-[60px] -translate-1/2"
      style={{ left: `${moon.x}%`, opacity: moon.opacity, top: `${moon.y}%` }}
    >
      <div
        className={cn(
          "absolute rounded-full",
          isHalo ? "-inset-10" : "inset-0"
        )}
        style={{
