function GlassBeads({ beads }: { readonly beads: readonly Bead[] }) {
  return (
    <div className="absolute inset-0">
      {beads.map((bead) => (
        <span
          key={bead.id}
          className={cn("absolute", bead.run > 0 && "gw-anim")}
          style={{
            animation:
              bead.run > 0
