  { opacity: 0.6, scale: 0.45, stretch: 1, x: 24, y: 132 },
];

const GOLDEN_CUMULUS: readonly CloudSpec[] = [
  { opacity: 0.9, scale: 0.8, stretch: 0.9, x: 150, y: 96 },
  { opacity: 0.7, scale: 0.55, stretch: 0.9, x: 40, y: 70 },
